local _x
do
local ok,b=pcall(require,'bit')
if ok and b and b.bxor then _x=b.bxor else
_x=function(a,c)
local r,p=0,1
while a>0 or c>0 do
local x,y=a%2,c%2
if x~=y then r=r+p end
a=(a-x)/2 c=(c-y)/2 p=p*2
end
return r
end
end
end
